// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 amount, uint256 cfgUnlock, uint256 delay, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        cfgUnlock = bound(cfgUnlock, 0, 100);
        // delay strictly exceeds the configured unlock time -> admissible withdrawal window in P
        delay = bound(delay, cfgUnlock + 1, cfgUnlock + 1000);

        __InvMutHandleStub token = new __InvMutHandleStub();

        // whitelist the actor as governable (configured == false, so anyone may configure)
        address[] memory gs = new address[](1);
        gs[0] = actor;
        bool[] memory bs = new bool[](1);
        bs[0] = true;
        c.setGoverned(gs, bs);

        c.configureFlashGovernance(address(token), amount, cfgUnlock, false);

        // lock a flash governance decision for actor/target(this), emergency=true skips epoch check
        vm.prank(actor);
        c.assertGovernanceApproved(actor, address(this), true);

        // advance time beyond the unlock time (created time + cfgUnlock < now)
        vm.warp(block.timestamp + delay);

        vm.prank(actor);
        bool ok;
        try c.withdrawGovernanceAsset(address(this), address(token)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after the unlock time has passed, withdrawal must succeed.
        assertTrue(ok, "withdrawal after unlock must succeed");
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
